# Builds the reproducible part of the test corpus into corpus/files.
#   synthetic/  generated by edits-bench (sizes, damage, encryption, forms)
#   generated/  printed from corpus/sources with Edge, plus scans made from them
# Real-world files go in corpus/files/real/ by hand; see corpus/README.md.
param([switch]$Large)
$ErrorActionPreference = "Stop"
$root = Split-Path $PSScriptRoot -Parent
Set-Location $root

cargo build -p edits-bench --release
if ($LASTEXITCODE -ne 0) { exit 1 }
$bench = "target/release/edits-bench.exe"

if ($Large) { & $bench gen-corpus --large corpus/files } else { & $bench gen-corpus corpus/files }

$gen = Join-Path $root "corpus/files/generated"
New-Item -ItemType Directory -Force $gen | Out-Null
$edge = @(
  "${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe",
  "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe"
) | Where-Object { Test-Path $_ } | Select-Object -First 1
if (-not $edge) { Write-Warning "Edge not found; skipping printed PDFs"; exit 0 }

$profile = Join-Path $env:TEMP "edits-corpus-edge"
foreach ($src in Get-ChildItem corpus/sources/*.html) {
  $out = Join-Path $gen ($src.BaseName + ".pdf")
  $url = ([Uri]$src.FullName).AbsoluteUri
  # Edge reports progress on stderr; do not treat that as a failure.
  $ErrorActionPreference = "Continue"
  & $edge --headless --disable-gpu --no-pdf-header-footer --user-data-dir="$profile" --print-to-pdf="$out" $url 2>&1 | Out-Null
  $ErrorActionPreference = "Stop"
  # Edge returns before the file is flushed on some machines.
  for ($i = 0; $i -lt 50 -and -not (Test-Path $out); $i++) { Start-Sleep -Milliseconds 100 }
  Write-Host "  printed $($src.Name) -> generated/$($src.BaseName).pdf"
  & $bench make-scan $out (Join-Path $gen ($src.BaseName + "-scan.pdf"))
}
